INSERT INTO movie (id, title, category, production_year, description, price) VALUES (4, 'Wicked', 'Musical', 2024, 'Historia niezwykłej przyjaźni dwóch czarownic z krainy Oz - niezrozumianej Elphaby i popularnej Glindy.', 49.99);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (5, 'Avengers: Endgame', 'Akcja', 2019, 'Pozostali przy życiu członkowie Avengers łączą siły, aby cofnąć niszczycielskie działania Thanosa i przywrócić porządek we wszechświecie.', 39.99);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (6, 'Deadpool & Wolverine', 'Komedia', 2024, 'Pyskaty najemnik Wade Wilson łączy siły z niechętnym do współpracy Wolverinem, aby uratować swoje uniwersum.', 55.00);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (7, 'Spider-Man: Bez drogi do domu', 'Akcja', 2021, 'Peter Parker prosi Doktora Strange''a o pomoc, co prowadzi do niebezpiecznego pęknięcia w multiwersum.', 45.00);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (8, 'Król Rozrywki', 'Musical', 2017, 'Historia narodzin amerykańskiego przemysłu rozrywkowego i wizjonera, który stworzył światowej sławy cyrk.', 35.00);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (9, 'Free Guy', 'Komedia', 2021, 'Przeciętny urzędnik bankowy odkrywa, że jest w rzeczywistości postacią tła w brutalnej grze wideo.', 40.00);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (10, 'John Wick 4', 'Akcja', 2023, 'John Wick odkrywa sposób na pokonanie Najwyższej Rady, ale zanim odzyska wolność, musi zmierzyć się z potężnym wrogiem.', 49.99);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (11, 'La La Land', 'Musical', 2016, 'Początkująca aktorka i muzyk jazzowy zakochują się w sobie, próbując osiągnąć sukces w bezlitosnym Los Angeles.', 29.99);
INSERT INTO movie (id, title, category, production_year, description, price) VALUES (12, 'Strażnicy Galaktyki Vol. 3', 'Komedia', 2023, 'Peter Quill wyrusza wraz ze swoją drużyną na niezwykle niebezpieczną misję, aby uratować życie Rocketa.', 55.00);